(async () => {
  await document.fonts.ready;
  await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  const main = document.querySelector('@selector/layout.main');
  const tabs = document.querySelector('@selector/layout.tabs');
  const actions = document.querySelector('@selector/lightDesk.presetActions');
  const off = document.querySelector('@selector/lightDesk.manualOff');
  if (!main || !tabs || !actions || !off) throw new Error('Required phone action or shell region is missing');
  const page = document.querySelector('@selector/pages.presets');
  const viewport = { width: innerWidth, height: innerHeight };
  const mainBounds = main.getBoundingClientRect();
  const tabsBounds = tabs.getBoundingClientRect();
  const controls = [...actions.querySelectorAll('button'), off];
  const results = controls.map((button) => {
    const bounds = button.getBoundingClientRect();
    const hit = document.elementFromPoint(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2);
    return { text: button.textContent.trim(), top: bounds.top, bottom: bounds.bottom, left: bounds.left, right: bounds.right, width: bounds.width, height: bounds.height, unobscured: Boolean(hit && button.contains(hit)) };
  });
  const navigation = [...tabs.querySelectorAll('a')].map((link) => { const b = link.getBoundingClientRect(); const hit = document.elementFromPoint(b.x + b.width / 2, b.y + b.height / 2); const style = getComputedStyle(link); return { text: link.textContent.trim(), top: b.top, bottom: b.bottom, height: b.height, width: b.width, visible: style.visibility === 'visible' && Number(style.opacity) > 0, unobscured: Boolean(hit && link.contains(hit)) }; });
  const navClear = navigation.length === 3 && navigation.every((link) => link.text && link.visible && link.unobscured && link.height >= 44 && link.width >= 44 && link.top >= tabsBounds.top && link.bottom <= viewport.height);
  const clear = navClear && viewport.width === 390 && results.length === 3 && tabsBounds.height >= 90 && results.every((button) => button.height >= 44 && button.width >= 44 && button.top >= mainBounds.top && button.bottom <= Math.min(mainBounds.bottom, tabsBounds.top) + 0.5 && button.left >= 0 && button.right <= viewport.width && button.unobscured);
  page.dataset.lightdeskActionsClear = String(clear);
  return { viewport, mainBottom: mainBounds.bottom, navTop: tabsBounds.top, navHeight: tabsBounds.height, scrollTop: main.scrollTop, controls: results, navigation, clear };
})()

